bool GsGpuRenderer::dofBlurEnabled()
{
    int v = g_uiDofBlur.load(std::memory_order_relaxed);
    if (v < 0) { const char *e = std::getenv("PS2X_DOFMASK"); v = (e && std::atoi(e) == 2) ? 1 : 0; g_uiDofBlur.store(v, std::memory_order_relaxed); }
    return v != 0;
}
