                    static int s_mn = 0;
                    std::fprintf(stderr, "[maskread] flush #%d of page %u  segFrom=%zu  alpha>0 pixels=%zu\n",
                                 ++s_mn, fbp, m_segFrom,
                                 (size_t)std::count_if(px.begin(), px.end(),
                                     [](uint32_t v){ return (v >> 24) != 0u; }));
